import { useState } from 'react';
import { ArrowDown, ArrowLeft, ArrowRight, ArrowUpRight, Bot, BriefcaseBusiness, CalendarDays, Check, ChevronDown, Cloud, Code2, Compass, FileText, Filter, Layers3, Lightbulb, PenTool, Play, Search, ShieldCheck, Smartphone, Sparkles, Target, Trophy, Users, Workflow, X } from 'lucide-react';
