    <section className="home-proof section-pad"><div className="container proof-grid"><div><SectionIntro eyebrow="Achievements" title="Great work deserves" accent="to be celebrated." text="We want to share the milestones that matter — with the evidence and owner approval to back them up." /><Link className="text-link" to="/achievements">Explore achievements <ArrowUpRight size={15} /></Link></div>{achievements.length ? <div className="achievement-grid">{achievements.map((item) => <article className="achievement-card" key={item.id}><span className="service-icon"><Trophy size={18} /></span><span className="achievement-date">{item.date}</span><h3>{item.title}</h3><p>{item.description}</p></article>)}</div> : <div className="proof-empty"><span className="proof-icon"><Trophy size={22} /></span><div><span className="proof-kicker">Milestones, with receipts</span><h3>Ready for the real wins.</h3><p>No verified awards, certifications, customer outcomes, or company milestones were provided. This section is styled and ready for approved achievements.</p><Link className="text-link" to="/achievements">See the achievements page <ArrowUpRight size={14} /></Link></div><span className="proof-watermark" aria-hidden="true">✳</span></div>}</div></section>
