    <section className="home-data-section home-data-muted section-pad"><div className="container data-grid"><div><SectionIntro eyebrow="Achievements" title="Credibility, without" accent="the guesswork." text="We publish verified milestones only. No awards, customer outcomes, or certifications have been provided for this preview." /><EmptyState title={achievements.length ? 'Published achievements' : 'No verified achievements published yet'}>{achievements.length ? 'Browse confirmed company milestones.' : 'This space is ready for confirmed awards, milestones, or credentials.'}</EmptyState><Link className="text-link" to="/achievements">Achievements <ArrowUpRight size={14} /></Link></div><div><SectionIntro eyebrow="On the horizon" title="Upcoming" accent="projects." text="Only publicly approved project announcements belong here." /><EmptyState title={upcomingProjects.length ? 'Upcoming projects' : 'No upcoming projects announced'}>{upcomingProjects.length ? 'See confirmed project announcements.' : 'No upcoming project details have been provided for publication.'}</EmptyState><Link className="text-link" to="/upcoming-projects">Upcoming projects <ArrowUpRight size={14} /></Link></div></div></section>
