export function ProjectsPage() {
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState('All categories');
  const [status, setStatus] = useState('All statuses');
  const categories = ['All categories', ...new Set(projects.map((item) => item.category))];
  const statuses = ['All statuses', ...new Set(projects.map((item) => item.status))];
  const filtered = projects.filter((item) => {
    const matchesQuery = `${item.title} ${item.category} ${item.summary} ${item.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase());
    return matchesQuery && (category === 'All categories' || item.category === category) && (status === 'All statuses' || item.status === status);
  });
  return <>
    <PageHero eyebrow="Projects & concepts" title="Ideas, made" accent="more tangible." text="Explore illustrative project directions and sample AI concepts. No client engagements, released products, or outcomes are claimed." image={images.pageHeroes.projects}><Link className="button button-dark" to="/contact">Discuss an idea <ArrowUpRight size={16} /></Link></PageHero>
    <section className="work-list-section section-pad"><div className="container"><div className="work-disclaimer"><Sparkles size={18} /><p><strong>Editorial note.</strong> Entries marked Concept or Sample direction are clearly illustrative; they are not published client case studies.</p></div><div className="project-filters"><label className="search-field"><Search size={16} /><span className="sr-only">Search projects</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search project ideas" /></label><label className="filter-select-label"><Filter size={15} /><span className="sr-only">Filter by category</span><select value={category} onChange={(event) => setCategory(event.target.value)}>{categories.map((item) => <option key={item}>{item}</option>)}</select><ChevronDown size={14} /></label><label className="filter-select-label"><span className="sr-only">Filter by status</span><select value={status} onChange={(event) => setStatus(event.target.value)}>{statuses.map((item) => <option key={item}>{item}</option>)}</select><ChevronDown size={14} /></label></div><p className="result-count" aria-live="polite">{filtered.length} {filtered.length === 1 ? 'project direction' : 'project directions'}</p>{filtered.length ? <div className="project-grid project-grid-large">{filtered.map((item) => <Link className="project-card" to={`/projects/${item.slug}`} key={item.slug}><PhotoSlot src={item.image} alt={item.imageAlt} label="Sample project image" className="project-photo" /><div className="project-meta"><span>{item.category} · {item.status}</span><ArrowUpRight size={17} /></div><h3>{item.title}</h3><p>{item.summary}</p></Link>)}</div> : <EmptyState title="No project ideas match those filters">Try a different search, category, or status.</EmptyState>}</div></section>
    <CTA title="Your challenge could be next." text="Tell us what you are trying to change. We can explore the opportunity together." />
  </>;
}

export function ProjectDetailsPage() {
  const { projectId } = useParams();
  const project = projects.find((item) => item.slug === projectId);
  if (!project) return <section className="detail-page container"><Breadcrumbs items={[{ label: 'Projects', to: '/projects' }, { label: 'Project not found' }]} /><EmptyState title="This project direction is not available">The address may be incorrect, or the project may have been removed.</EmptyState><Link className="button button-dark" to="/projects"><ArrowLeft size={15} /> Back to projects</Link></section>;
  return <section className="detail-page container"><Breadcrumbs items={[{ label: 'Projects', to: '/projects' }, { label: project.title }]} /><div className="detail-layout"><div className="detail-copy"><Eyebrow>{project.category} · {project.status}</Eyebrow><h1>{project.title}</h1><p className="detail-lede">{project.summary}</p><div className="work-disclaimer"><Sparkles size={18} /><p><strong>Illustrative concept.</strong> This is sample content for the website preview, not a shipped product or client engagement.</p></div><h2>About this direction</h2><p>{project.description}</p><div className="tag-list">{project.tags.map((tag) => <span key={tag}>{tag}</span>)}</div><Link className="button button-dark" to="/contact">Discuss a similar idea <ArrowUpRight size={15} /></Link></div><PhotoSlot className="detail-photo" src={project.image} alt={project.imageAlt} label="Sample project image" /></div></section>;
}

