    <section className="ecosystem-section section-pad"><div className="container"><SectionIntro eyebrow="The SyncCommit technology ecosystem" title="Good connections" accent="make things happen." text="A practical view of the capabilities and technology foundations that support useful products." /><div className="ecosystem-grid">{pillars.map((item) => <article className="ecosystem-card" key={item.num}><span className="ecosystem-icon">{item.icon}</span><span className="ecosystem-num">{item.num}</span><h3>{item.title}</h3><p>{item.text}</p><span className="ecosystem-rule" /></article>)}</div></div></section>
