export function CareersPage() {
  const [careerFilter, setCareerFilter] = useState('All areas');
  const careerAreas = ['All areas', 'Product & strategy', 'Design', 'Engineering', 'AI & automation', 'Operations', 'Other'];
  const filteredJobs = careerFilter === 'All areas' ? jobOpenings : jobOpenings.filter((job) => job.category === careerFilter);
  return <>
    <PageHero eyebrow="Careers at SyncCommit" title="Bring your point" accent="of view." text="For people who care about making technology more useful. Bring your craft, your questions, and your ideas." image={images.pageHeroes.careers}><a className="button button-dark" href="#introduce-yourself">Introduce yourself <ArrowDown size={16} /></a></PageHero>
    <section className="careers-values section-pad"><div className="container"><SectionIntro eyebrow="A good place to do good work" title="Room to think." accent="Space to make." text="We value open collaboration, thoughtful craft, and the belief that better work comes from learning together." /><div className="career-perks"><article><span>01</span><h3>Meaningful challenges</h3><p>Work on real problems and help shape what a good solution looks like.</p></article><article><span>02</span><h3>Work in the open</h3><p>Share ideas early, learn together, and give good work room to evolve.</p></article><article><span>03</span><h3>Keep growing</h3><p>Bring your perspective, build new skills, and help the team get better.</p></article></div></div></section>
    <section className="open-roles-section section-pad"><div className="container"><div className="section-heading-row"><SectionIntro eyebrow="Current opportunities" title="Find your next" accent="good challenge." text="Only confirmed, currently open roles appear here. No role or employer claim is inferred." /><label className="filter-select-label career-filter"><Filter size={15} /><span className="sr-only">Filter openings by area</span><select value={careerFilter} onChange={(event) => setCareerFilter(event.target.value)}>{careerAreas.map((area) => <option key={area}>{area}</option>)}</select><ChevronDown size={14} /></label></div>{filteredJobs.length ? <div className="job-grid">{filteredJobs.map((job) => <Link className="job-card" to={`/careers/${job.slug}`} key={job.slug}><span className="service-icon"><BriefcaseBusiness size={18} /></span><span className="job-type">{job.category} · {job.type}</span><h3>{job.title}</h3><p>{job.summary}</p><span className="text-link">View job details <ArrowUpRight size={14} /></span></Link>)}</div> : <EmptyState title={careerFilter === 'All areas' ? 'No confirmed openings right now' : `No confirmed openings in ${careerFilter}`}>There are no approved job listings right now. You can still introduce yourself below.</EmptyState>}</div></section>
    <section className="application-section section-pad" id="introduce-yourself"><div className="container application-grid"><div><Eyebrow>Start a conversation</Eyebrow><h2>Tell us what makes you <span>you.</span></h2><p>Share your area of interest and a link to your work or profile. The form validates locally and is not connected to a hiring inbox.</p></div><div className="form-card"><DemoForm kind="career" /></div></div></section>
  </>;
}

