export function EventsPage() {
  const [view, setView] = useState('upcoming');
  const now = Date.now();
  const matchingEvents = events.filter((event) => view === 'upcoming' ? new Date(event.endDate ?? event.date).getTime() >= now : new Date(event.endDate ?? event.date).getTime() < now);
  return <>
    <PageHero eyebrow="Conferences & meetups" title="Meet, share," accent="keep learning." text="Find confirmed conferences, meetups, and moments where people come together around useful technology." image={images.pageHeroes.events}><Link className="button button-dark" to="/contact">Ask about an event <ArrowUpRight size={16} /></Link></PageHero>
    <section className="events-section section-pad"><div className="container"><SectionIntro eyebrow="Events calendar" title="Good ideas travel" accent="in company." text="Event details appear here only after dates and participation information are confirmed." /><div className="event-tabs" role="tablist" aria-label="Choose event period"><button role="tab" aria-selected={view === 'upcoming'} className={view === 'upcoming' ? 'event-tab active' : 'event-tab'} onClick={() => setView('upcoming')} type="button">Upcoming</button><button role="tab" aria-selected={view === 'past'} className={view === 'past' ? 'event-tab active' : 'event-tab'} onClick={() => setView('past')} type="button">Past events</button></div>{matchingEvents.length ? <div className="event-grid">{matchingEvents.map((event) => <article className="event-card" key={event.id}><PhotoSlot src={event.image} alt={event.imageAlt} label="Conference or meetup photo" /><div className="event-card-body"><span className="event-date"><CalendarDays size={14} />{event.displayDate}</span><h3>{event.title}</h3><p>{event.summary}</p><span className="event-venue">{event.venue} · {event.format}</span></div></article>)}</div> : <EmptyState title={view === 'upcoming' ? 'No upcoming events confirmed' : 'No past events published'}>{view === 'upcoming' ? 'Conference and meetup details will appear when the dates and information are confirmed.' : 'Past events will be listed here after approved event details and photos are available.'}</EmptyState>}</div></section>
    <CTA title="Organizing a meetup or conference?" text="Share confirmed details and we can explore how to take part." />
  </>;
}

export function JobDetailsPage() {
  const { jobId } = useParams();
  const job = jobOpenings.find((opening) => opening.slug === jobId);
  return <section className="detail-page container"><Breadcrumbs items={[{ label: 'Careers', to: '/careers' }, { label: job?.title ?? 'Job details' }]} />{job ? <div className="job-detail-layout"><div><Eyebrow>{job.category} · {job.type}</Eyebrow><h1>{job.title}</h1><p className="detail-lede">{job.summary}</p><p className="preview-note">Opening status: {job.status}. Details supplied by the hiring owner.</p><h2>About the role</h2><p>{job.description}</p><h2>What you'll bring</h2><ul className="detail-list">{job.requirements.map((requirement) => <li key={requirement}>{requirement}</li>)}</ul><a className="button button-dark" href="#apply">Apply for this role <ArrowDown size={15} /></a></div><PhotoSlot className="detail-photo" src={job.image} alt={job.imageAlt} label="Role image" /></div> : <div className="job-detail-empty"><Eyebrow>Job details</Eyebrow><h1>No confirmed opening at this address.</h1><p>SyncCommit has not supplied active job listings for this preview. No vacancy or hiring status is implied.</p><PhotoSlot className="job-empty-photo" src={images.pageHeroes.careers.src} alt={images.pageHeroes.careers.alt} label="Add an approved careers photo" /><Link className="button button-outline" to="/careers">Browse careers <ArrowRight size={15} /></Link><div className="general-interest"><h2>Still interested?</h2><p>No current vacancy is being advertised. A general introduction can be validated locally but is not transmitted or retained.</p></div></div>}{<div className="job-apply" id="apply"><div><Eyebrow>{job ? 'Application preview' : 'General interest preview'}</Eyebrow><h2>{job ? 'Introduce yourself.' : 'Share an introduction.'}</h2><p>This demo validates locally only. It is not connected to a hiring system.</p></div><div className="form-card"><DemoForm kind="career" /></div></div>}</section>;
}

